/* Original body skin selection. The embedded alpha mask excludes clothes, shoes and nails. */
(() => {
  'use strict';
  const maskSource='data:image/png;base64,';
  const shoeMaskSources={"shoe-ballet-left": "data:image/png;base64,", "shoe-ballet-right": "data:image/png;base64,", "shoe-strap-left": "data:image/png;base64,", "shoe-strap-right": "data:image/png;base64,", "shoe-boots-left": "data:image/png;base64,", "shoe-boots-right": "data:image/png;base64,"};
  const nailMaskSources={"hands": "data:image/png;base64,", "feet": "data:image/png;base64,"};
  let serial=0;
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
  function paintSkin(state,asset,markup,selection) {
    const studio=window.PrincessFaceStudio;
    if(!state||state.photoUrl||state.faceStudioEnabled!==true||state.faceOptions?.enabled!==true||!studio?.skinFilterDefinition||!asset?.src||!selection)return markup;
    const id='body-skin-'+(++serial),mask=id+'-mask',filter=studio.skinFilterDefinition(id,state.faceOptions);
    if(typeof filter!=='string'||!filter.includes('<filter'))return markup;
    let images=0;
    const source='href="'+esc(asset.src)+'"';
    const painted=markup.replace(/<image\b[^>]*\/>/g,tag=>{
      if(!tag.includes(source))return tag;
      images++;
      // Keep each original clip and insert the skin beneath later nail polish or clothing layers.
      const tinted=tag.replace(/\sfilter="[^"]*"/g,'').replace(/\/>$/,` filter="url(#${id})"/>`);
      return tag+`<g class="body-skin-painted" mask="url(#${mask})">${tinted}</g>`;
    });
    if(!images)return markup;
    return `<g class="body-skin-tone"><defs>${filter}<mask id="${mask}" maskUnits="userSpaceOnUse" maskContentUnits="userSpaceOnUse" x="${asset.x}" y="${asset.y}" width="${asset.w}" height="${asset.h}" style="mask-type:alpha"><image href="${selection}" x="${asset.x}" y="${asset.y}" width="${asset.w}" height="${asset.h}" preserveAspectRatio="none"/></mask></defs>${painted}</g>`;
  }
  function sceneBody(state,asset,markup){return paintSkin(state,asset,markup,maskSource);}
  function sceneShoes(state,shoe,markup){
    for(const [index,part] of (shoe?.parts||[]).entries())markup=paintSkin(state,part,markup,shoeMaskSources['shoe-'+shoe.id+'-'+(index?'right':'left')]);
    return markup;
  }
  function sceneNails(state,markup){
    const studio=window.PrincessFaceStudio;
    if(!state||state.photoUrl||state.faceStudioEnabled!==true||state.faceOptions?.enabled!==true||!studio?.skinFilterDefinition)return markup;
    const mode=state.mode==='feet'?'feet':'hands',source=window.PrincessAssets?.nailArt?.[mode];
    if(!source)return markup;
    const asset={src:source,x:0,y:0,w:1536,h:1024};let painted=false;
    return markup.replace(/<image\b[^>]*\/>/g,tag=>{
      if(painted||/\sfilter=/.test(tag))return tag;
      painted=true;return paintSkin(state,asset,tag,nailMaskSources[mode]);
    });
  }
  window.PrincessBodySkin={sceneBody,sceneShoes,sceneNails};
})();
